DROP TABLE IF EXISTS posts;

CREATE TABLE IF NOT EXISTS api_keys( id SERIAL PRIMARY KEY, user_id INTEGER NOT NULL, CONSTRAINT fk_api_keys_user_id FOREIGN KEY (user_id) REFERENCES users (id) MATCH SIMPLE ON UPDATE CASCADE ON DELETE CASCADE, label VARCHAR(255), key_prefix VARCHAR(50) NOT NULL, key_hash TEXT NOT NULL UNIQUE, scopes VARCHAR(255), created_at TIMESTAMP DEFAULT NOW(), last_used_at TIMESTAMP NULL, expires_at TIMESTAMP NOT NULL, revoked_at TIMESTAMP NULL);